package com.budgetowl.bill.service;

import com.budgetowl.bill.domain.BillOccurrence;
import java.time.LocalDate;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Merges a bill's projected dates for a period with whatever was recorded against it.
 *
 * <p><b>A pure function.</b> No clock, no database, no household — which is what lets a period be
 * answered on read instead of generated by a job (ADR-0032), and what makes the awkward case below
 * testable without either.
 *
 * <p>The awkward case is a schedule that changed after a period was settled. ADR-0032 sets out the
 * three steps and this is them:
 *
 * <ol>
 *   <li>a recorded row whose due date <b>is</b> a projected date is that occurrence;
 *   <li>leftover rows are matched to leftover dates <b>in date order</b>, so moving a monthly bill
 *       from the 15th to the 20th leaves a settled month settled rather than showing a paid 15th
 *       beside an unpaid 20th;
 *   <li>a row still left over is kept as it stands — the household asserted it, and editing a
 *       schedule does not get to delete it.
 * </ol>
 */
final class OccurrenceProjection {

    private OccurrenceProjection() {}

    /**
     * @param projected the schedule's dates for the period, in order. Empty for an {@code
     *     IRREGULAR} bill and for a {@code YEARLY} one outside its month
     * @param recorded the rows stored for that period, in any order
     * @return every occurrence the period has, by due date
     */
    static List<ProjectedOccurrence> merge(
            List<LocalDate> projected, List<BillOccurrence> recorded) {
        if (recorded.isEmpty()) {
            return projected.stream().map(date -> new ProjectedOccurrence(date, null)).toList();
        }

        Map<LocalDate, BillOccurrence> exact = new HashMap<>();
        for (BillOccurrence row : recorded) {
            exact.put(row.dueDate(), row);
        }

        List<LocalDate> unmatchedDates = new ArrayList<>();
        Map<LocalDate, BillOccurrence> matched = new HashMap<>();
        for (LocalDate date : projected) {
            BillOccurrence row = exact.remove(date);
            if (row == null) {
                unmatchedDates.add(date);
            } else {
                matched.put(date, row);
            }
        }

        // Step 2: whatever is left, paired up in date order. Both sides are sorted, so the pairing
        // is deterministic — two members reading the same month see the same thing.
        Deque<BillOccurrence> leftovers =
                new ArrayDeque<>(
                        exact.values().stream()
                                .sorted(Comparator.comparing(BillOccurrence::dueDate))
                                .toList());
        for (LocalDate date : unmatchedDates) {
            if (leftovers.isEmpty()) {
                break;
            }
            matched.put(date, leftovers.removeFirst());
        }

        List<ProjectedOccurrence> merged = new ArrayList<>(projected.size() + leftovers.size());
        for (LocalDate date : projected) {
            merged.add(new ProjectedOccurrence(date, matched.get(date)));
        }
        // Step 3: rows that line up with nothing. Shown on their own stored date.
        for (BillOccurrence orphan : leftovers) {
            merged.add(new ProjectedOccurrence(orphan.dueDate(), orphan));
        }
        merged.sort(Comparator.comparing(ProjectedOccurrence::dueDate));
        return merged;
    }
}
